select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Gemini Notebook (formerly NotebookLM)' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Le carnet de recherche de Google : il lit vos sources (PDF, sites, vidéos), répond en citant ses sources et produit résumés, fiches d''étude et résumés audio.',
  'Google''s research notebook: it reads your sources (PDFs, sites, videos), answers with citations, and produces summaries, study guides and Audio Overviews.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Krisp AI Note Taker' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Assistant de réunion IA qui enregistre, transcrit et résume les appels sur toutes les plateformes, avec suppression du bruit, actions à mener et notes CRM.',
  'AI meeting assistant that records, transcribes and summarizes calls on any platform, with noise cancellation, action items and CRM notes.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Kimi' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'L''assistant de Moonshot AI avec des modes agents : rapports Deep Research, présentations, sites et documents créés à partir d''une seule demande, et Kimi Code pour programmer.',
  'Moonshot AI''s assistant with agent modes: Deep Research reports, slides, websites and documents built from one request, and Kimi Code for programming.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Kustomer AI Agents' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Agents IA autonomes qui règlent les conversations clients par e-mail, chat, SMS, WhatsApp et téléphone, et transmettent les cas complexes aux conseillers humains.',
  'Autonomous AI agents that resolve customer conversations across email, chat, SMS, WhatsApp and voice, and hand complex cases to human agents.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Emergent' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Créateur d''applications par agents : décrivez une idée en langage courant et ses agents écrivent le code, conçoivent l''interface et mettent en ligne une application qui fonctionne.',
  'Agentic app builder: describe an idea in plain language and its agents write the code, design the interface and deploy a working app.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'UiPath Agents' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme d''automatisation agentique : agents IA, robots et humains travaillent ensemble sur des processus métier comme les factures, sinistres ou intégrations, sous une gouvernance centrale.',
  'Agentic automation platform: AI agents, robots and people work together on business processes such as invoices, claims and onboarding, under central governance.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Glean Agents' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Plateforme d''IA d''entreprise qui cherche dans tous les outils de l''entreprise en respectant les droits d''accès, et permet de créer, partager et encadrer des agents IA.',
  'Enterprise AI platform that searches all company tools with permissions, and lets teams build, share and govern AI agents for everyday work.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Legora' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'IA collaborative pour avocats : son Agent Pro planifie et réalise des travaux juridiques complexes, de la recherche à la revue et à la rédaction, pour cabinets et services juridiques.',
  'Collaborative AI for lawyers: its Agent Pro plans and carries out complex legal work, from research and review to drafting, for law firms and legal teams.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Nooks' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
