select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'ClickUp Brain (AI agents)' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'L''IA et les agents de ClickUp travaillent sur les tâches, documents et messages : ils répondent aux questions sur votre travail, rédigent des points d''avancement, trient les demandes et lancent des processus.',
  'ClickUp''s AI and agents work across tasks, docs and chat: they answer questions about your work, write updates, triage requests and run workflows.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Abacus.AI ChatLLM & DeepAgent' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Super-assistant IA donnant accès à de nombreux modèles, avec DeepAgent, un agent qui crée applications, rapports et présentations et réalise des tâches en plusieurs étapes.',
  'AI super-assistant with access to many models, and DeepAgent, an agent that builds apps, reports and presentations and carries out multi-step tasks.');
select i18n_set('agent', (select e.slug from entities e where e.type = 'agent' and e.name = 'Taskade AI Agents' order by e.first_seen_at desc limit 1), 'fr', 'short_description',
  'Espace de travail où vous créez des agents IA dotés d''outils et de mémoire, reliés à vos projets et automatisations, à partager ou intégrer à un site sans code.',
  'Workspace where you build AI agents with tools and memory, connect them to projects and automations, and share them or embed them on a website without code.');

select refresh_rankings();

select e.name, 'https://electraindex.com/agents/' || e.slug as page,
       (select count(*) from entities x where x.type = 'agent' and x.is_published) as agents_total
  from entities e where e.type = 'agent' and e.name in ('Gemini Notebook (formerly NotebookLM)', 'Krisp AI Note Taker', 'Kimi', 'Kustomer AI Agents', 'Emergent', 'UiPath Agents', 'Glean Agents', 'Legora', 'Nooks', 'ClickUp Brain (AI agents)', 'Abacus.AI ChatLLM & DeepAgent', 'Taskade AI Agents') order by e.name;
